var hits = [];
Memory.scan(mod.base, mod.size, hex, {
    onMatch(addr, size) {
        hits.push(addr.toString());
        send("  found: " + addr);
        if (hits.length >= 20) return "stop";
    },
    onComplete() { send("[*] 共命中 " + hits.length + " 处"); }
});

