var sym = Module.getExportByName(null, "RegisterNatives");
Interceptor.attach(sym, {
    onEnter(args) {
        var env = args[0], clazz = args[1], methods = args[2], count = args[3].toInt32();
        var cls = Java.vm.getEnv().getObjectClass(clazz);
        var name = Java.vm.getEnv().getClassName(cls);
        send("[RegisterNatives] " + name + " count=" + count);
        for (var i = 0; i < count; i++) {
            var m = methods.add(i * Process.pointerSize * 3);
            send("  " + m.readPointer().readCString() + " -> " + m.add(Process.pointerSize * 2).readPointer());
        }
    }
});
